<script setup>
import{ref,onUnmounted}from'vue';import{Head}from'@inertiajs/vue3';import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';import{useFamilyCopy}from'@/lib/family';
const{l}=useFamilyCopy();const token=ref(''),result=ref(null),error=ref(''),confirmed=ref(false),saved=ref(false),busy=ref(false),camera=ref(false),video=ref(null);let controls;
function stop(){controls?.stop();controls=null;camera.value=false;}
onUnmounted(stop);
async function verify(){error.value='';result.value=null;confirmed.value=false;saved.value=false;busy.value=true;try{const{data}=await window.axios.post('/pickup-scan/verify',{token:token.value.trim()});result.value=data;}catch(e){error.value=e.response?.data?.message||l('الرمز غير صالح أو انتهت صلاحيته.','Invalid or expired code.');}finally{busy.value=false;}}
async function scan(){error.value='';camera.value=true;try{const{BrowserQRCodeReader}=await import('@zxing/browser');const reader=new BrowserQRCodeReader();controls=await reader.decodeFromVideoDevice(undefined,video.value,(r)=>{if(r){token.value=r.getText();stop();verify();}});}catch{stop();error.value=l('تعذر فتح الكاميرا. اسمح بها أو استخدم الرمز المقروء من جهاز آخر.','Camera unavailable. Allow camera access or paste the code read on another device.');}}
async function checkout(){if(!confirmed.value||!result.value)return;busy.value=true;try{await window.axios.post('/pickup-scan/checkout',{token:token.value.trim(),identity_confirmed:true});saved.value=true;result.value=null;token.value='';confirmed.value=false;}catch(e){error.value=e.response?.data?.message||l('لم يسجل الاستلام. تحقق من الحالة والصلاحية.','Pickup was not recorded. Check the current status and authorization.');result.value=null;}finally{busy.value=false;}}
</script>
<template><Head :title="l('استلام برمز مؤقت','Temporary pickup code')"/><AuthenticatedLayout><div class="family-main"><header class="family-heading"><h1>{{l('استلام موثق. وهوية واضحة.','A recorded handover. A verified person.')}}</h1><p class="family-muted">{{l('الرمز يعثر على التفويض ولا يثبت الهوية. طابق المستلم مع الشخص المعتمد قبل تسليم الطفل.','The code locates authorization, not identity. Match the person at the door to the approved pickup person before handing over the child.')}}</p></header><section class="family-card family-auth"><button class="family-primary w-full" @click="camera?stop():scan()">{{camera?l('إيقاف الكاميرا','Stop camera'):l('مسح رمز الاستلام','Scan pickup QR')}}</button><video v-show="camera" ref="video" class="w-full mt-4 rounded-xl" playsinline muted/><form class="family-form" @submit.prevent="verify"><label>{{l('أو الصق الرمز المقروء','Or paste the scanned code')}}<input v-model="token" autocomplete="off" spellcheck="false" dir="ltr" required/></label><button class="family-secondary" :disabled="busy">{{l('مراجعة التفويض','Review authorization')}}</button></form><p v-if="error" role="alert" class="family-error mt-4">{{error}}</p><p v-if="saved" role="status" class="family-success mt-4">{{l('تم تسجيل الاستلام. لا يمكن استخدام هذا الرمز مجدداً.','Pickup recorded. This code cannot be used again.')}}</p><div v-if="result" class="mt-6"><h2>{{result.child}}</h2><p>{{l('المستلم المعتمد','Approved pickup person')}}: <strong>{{result.pickup_person}}</strong></p><p class="family-muted">{{l('ينتهي الرمز','Code expires')}}: {{result.expires_at}}</p><label class="family-form check"><input v-model="confirmed" type="checkbox"/>{{l('تحققت فعلياً من هوية هذا الشخص وطابقتها مع التفويض قبل تسليم الطفل.','I physically checked this person’s identity and matched it to the authorization before handing over the child.')}}</label><button class="family-primary w-full mt-5" :disabled="busy||!confirmed" @click="checkout">{{l('تأكيد وتسجيل الاستلام','Confirm and record pickup')}}</button></div></section></div></AuthenticatedLayout></template>
